import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    types = []
    for _ in range(n):
        types.append(int(next(iterator)))

    tracks_in = [0] * (n + 1)
    for i in range(1, n + 1):
        val = int(next(iterator))
        tracks_in[i] = val

    next_node = [0] * (n + 1)
    for i, u in enumerate(tracks_in[1:], start=1):
        if u != 0:
            next_node[u] = i

    best_len = 0
    best_start = 1

    for i in range(1, n + 1):
        if types[i - 1] == 1:
            current_len = 1
            curr = i
            while True:
                prev = tracks_in[curr]
                if prev == 0:
                    break
                if types[prev - 1] == 1:
                    break
                curr = prev
                current_len += 1

            if current_len > best_len:
                best_len = current_len
                best_start = curr

    path = []
    curr = best_start
    while True:
        path.append(curr)
        nxt = next_node[curr]
        if nxt == 0:
            break
        curr = nxt

    print(best_len)
    print(' '.join(map(str, path)))

if __name__ == "__main__":
    main()
